/* Content model for the static OOP Interview Studio. No build process required. */
const entry = (id, title, definition, example, trap, answer, extra = {}) => ({ id, title, definition, example, trap, answer, ...extra });
const section = (id, number, title, subtitle, accent, topics) => ({ id, number, title, subtitle, accent, topics });

window.CURRICULUM = [
  section('foundations','01','Core concepts','The vocabulary every explanation builds on.','Core',[
    entry('encapsulation','Encapsulation','Keep an object’s state and the rules for changing it behind a deliberate public API. Hiding fields is a mechanism; preserving invariants is the goal.','A BankAccount exposes deposit(amount) and withdraw(amount) rather than letting callers mutate balance.','A public getter returning a mutable internal List can break encapsulation even when the field is private.','Encapsulation protects invariants by restricting how state changes. I expose behavior rather than unrestricted state.'),
    entry('abstraction','Abstraction','Expose the essential contract while hiding implementation choices. Clients should know what an object can do, not how it does it.','PaymentGateway.charge(amount) could call Stripe, a bank API, or a test double without changing its consumer.','Abstraction and encapsulation are related but different: abstraction hides complexity; encapsulation protects internal state.','Abstraction gives consumers a stable contract independent of implementation.'),
    entry('inheritance','Inheritance','An is-a relationship where a derived type acquires and specializes a parent’s contract or implementation. Only use it when substitutability holds.','An ElectricVehicle may extend Vehicle when it can honor all Vehicle operations.','Reusing code is insufficient justification. A Square extending mutable Rectangle commonly violates substitutability.','I use inheritance for a genuine is-a relationship, not just because classes share code.'),
    entry('polymorphism','Polymorphism','Different concrete types can satisfy the same interface, allowing a call to have type-specific behavior without branching at every call site.','render(Shape shape) invokes Circle.render() or Rectangle.render() using the same contract.','Polymorphism includes subtype, parametric, and ad-hoc forms; overloading is not dynamic dispatch.','Polymorphism lets clients depend on a contract while implementations vary.'),
    entry('class-object','Class vs object','A class describes structure and behavior; an object is a runtime instance with identity and state. Some languages use prototypes instead of classes.','User is a class; the User instance representing account 42 is an object.','A class itself has metadata and possibly static storage; the shorthand “class occupies zero memory” is not literally true.','A class is a blueprint or type definition; an object is an instance carrying state and identity.'),
    entry('access','Access modifiers','public exposes APIs; private restricts access to the declaring class; protected includes subclasses under language-specific rules; package-private/default in Java restricts access to the package.','Keep a Java Order.total private, expose calculateTotal(), and use package-private helpers within a module.','Java protected also provides package access. Java default means package-private, not a special default keyword.','Choose the narrowest visibility that meets collaboration requirements.'),
    entry('static-dynamic','Static vs dynamic polymorphism','Overload selection commonly happens at compile time using declared argument types. Overridden instance method selection happens at runtime based on the receiver’s actual type.','print(String) vs print(Object) is resolved during compilation; Animal.speak() calling Dog.speak() dispatches dynamically.','Java static methods are hidden, not overridden; field access is not polymorphic.','Overloading selects a signature at compile time; overriding selects an implementation at runtime.'),
    entry('overload-override','Overloading vs overriding','Overloading: same method name, different parameter lists. Overriding: subclass replaces an inherited instance method with a compatible signature and contract.','sum(int,int) and sum(double,double) overload; Bird.move() overriding Animal.move() is overriding.','Return type alone cannot overload a Java method; narrower checked exceptions and covariant return types matter for overrides.','Overloads differ by parameters; overrides keep the contract and specialize runtime behavior.'),
    entry('this-super','this and super','this refers to the current instance; super accesses inherited members or invokes the parent constructor. Constructor chaining avoids duplicating initialization.','A constructor calls this(name, defaultRole), or super(id) to initialize a base class.','In Java this(...) and super(...) cannot both appear as constructor-invocation statements in the same constructor.','this targets the current object; super targets parent initialization or implementation.'),
    entry('static-instance','Static vs instance state','Static members belong to a class-level context; instance members belong to each object. Static methods do not have an implicit instance receiver.','A shared cache configuration may be static; each Cart has its own items and subtotal.','Mutable static fields are global shared state and create testing and concurrency risks.','Store per-object state in instance fields, shared class-wide constants in static final fields.'),
    entry('constructors','Constructor types','A constructor establishes a valid object. Java has implicit no-arg defaults only when no constructor is declared; explicit no-arg and parameterized constructors; copy constructors are a convention, not a built-in language feature.','new Money(120, "INR"); new Money(existing); and this(0, "INR") chaining.','Constructor overloads should maintain one source of truth for validation.','Use constructors to establish invariants; chain to one canonical initialization path.'),
    entry('lifecycle','Destructors and finalizers','C++ destructors deterministically release owned resources through RAII. Python __del__ and Java finalization are not reliable primary cleanup mechanisms. Java finalization is deprecated for removal.','Use Java try-with-resources, Python with, or C++ scoped objects to close files and sockets.','GC recovers memory, not necessarily external resources promptly; __del__ timing can vary.','Prefer explicit or scope-bound resource cleanup rather than relying on finalizers.'),
    entry('final-sealed-const','final / sealed / const','Java final prevents reassignment, overrides, or inheritance depending on position; sealed restricts permitted subclasses; C++ const restricts mutation through a path.','A final Java class cannot be subclassed; sealed Shape permits Circle and Rect; const methods promise not to modify observable object state in C++.','A final reference in Java does not make the referenced object immutable.','These features constrain extension or mutation, but exact semantics depend on the language.'),
  ]),
  section('relationships','02','Inheritance & composition','Model relationships without creating brittle hierarchies.','Design',[
    entry('inheritance-types','Inheritance types','Single: one immediate base; multiple: several bases; multilevel: A→B→C; hierarchical: multiple children; hybrid: a combination. Support differs by language.','Vehicle→Car is single; Animal→Mammal→Dog is multilevel; Dog and Cat from Animal are hierarchical.','Java classes cannot extend multiple classes, although classes can implement multiple interfaces.','Explain the structural shape, then mention your language’s restrictions.'),
    entry('diamond','The diamond problem','If D inherits from B and C, both derived from A, which A implementation/state should D receive? Different languages resolve this differently.','C++ virtual inheritance can share one A base subobject; Python follows a consistent MRO; Java avoids multiple class inheritance.','Default methods from conflicting Java interfaces may need an explicit override; interfaces do not erase all ambiguity.','The diamond problem is conflicting or duplicated ancestor behavior; resolution is language-specific.'),
    entry('association','Association','A general relationship between objects without implying strong lifetime ownership. Can be one-to-one, one-to-many, or many-to-many.','Doctor treats Patient; both live independently.','Association does not automatically mean “contains” or imply cascading deletion.','Association says objects know about or interact with each other.'),
    entry('aggregation','Aggregation','A weak whole–part relationship: a container references parts that can exist independently. In UML it uses a hollow diamond.','Team has Players; players can exist after a team dissolves.','Many real-world relationships are best represented as ordinary associations; do not overuse aggregation diamonds.','Aggregation groups existing objects without owning their lifecycle.'),
    entry('composition','Composition','A strong whole–part ownership model: parts are conceptually owned by one whole and have a lifecycle tied to it. UML uses a filled diamond.','An Order owns its OrderLine items; deleting the order usually removes the lines.','Composition means ownership/lifetime semantics, not simply a field holding another object.','Composition says the whole controls its component parts and lifecycle.'),
    entry('composition-over-inheritance','Composition over inheritance','Delegate behavior to collaborators instead of tying variation to a parent hierarchy. It limits coupling and supports independent behavior changes.','A NotificationService receives a DeliveryChannel rather than extending EmailNotificationService or SmsNotificationService.','Inheritance is still appropriate for a stable, truthful subtype relationship with enforced contracts.','I prefer composition for replaceable capabilities, inheritance for genuine substitutable specialization.'),
    entry('deep-hierarchies','Deep inheritance drawbacks','Deep hierarchies hide behavior across many classes, produce fragile base-class problems, increase coupling, and make changes hard to reason about.','A 7-level UI widget hierarchy requires reading ancestors to understand one draw() call.','Replacing every inheritance tree with delegation can itself overcomplicate the design.','Favor shallow contracts and well-scoped collaborators over unnecessary depth.'),
    entry('abstract-interface','Abstract class vs interface','An abstract class can share state, constructors, and partial implementation; an interface specifies a role/capability and supports multiple independent implementations.','AbstractBaseRepository can hold reusable transaction logic; Cacheable and Auditable model capabilities.','Modern Java interfaces allow default/static/private methods; the distinction is not simply “interfaces have no implementation.”','Use an interface to describe a capability; an abstract class for tightly related implementations sharing state or invariants.'),
    entry('mixins-traits','Mixins and traits','Reusable units of behavior that add capabilities without forcing everything into one superclass chain. Conflict handling varies by language.','Python mixins add serialization helpers; Scala traits combine behavior; Java interfaces express related capabilities.','Avoid mixins with undocumented state or ordering assumptions.','Traits and mixins provide modular behavior reuse while reducing deep inheritance.'),
    entry('multiple-lang','Multiple inheritance by language','Java: single class inheritance plus multiple interfaces. C++: multiple bases and virtual inheritance. Python: multiple inheritance resolved using C3 method-resolution order.','class D(B,C) in Python looks up methods using D.__mro__; C++ class D : public B, public C.','A Java interface default-method conflict must be resolved; Python super() follows MRO, not always one lexical parent.','The language determines how shared bases and conflicting method implementations are resolved.'),
  ]),
  section('solid','03','SOLID principles','Five heuristics for boundaries, change, and substitution.','Principles',[
    entry('srp','Single Responsibility Principle','A module should have one reason to change—one cohesive responsibility aligned with one stakeholder or policy axis. Not “one method per class.”','Violation: Invoice calculates tax, writes PDF, and sends mail. Fix: InvoiceCalculator, PdfRenderer, EmailSender.','Excessive splitting leads to anemic one-method abstractions with no cohesive domain logic.','Split responsibilities when they change for independent reasons, not merely because a class is long.'),
    entry('ocp','Open/Closed Principle','Stable policy should be extendable through new implementations instead of repeatedly editing central conditional logic.','Violation: DiscountCalculator has switch by member type. Fix: DiscountPolicy interface with membership-specific strategies.','Do not build plugin architectures for variations that will probably never exist.','Define a stable extension point where real variation exists; keep common logic untouched.'),
    entry('lsp','Liskov Substitution Principle','A subtype must preserve the behavioral promises of its supertype: preconditions must not strengthen, postconditions must not weaken, and invariants must hold.','Violation: ReadOnlyFile extends WritableFile but throws on write(). Fix: separate Readable and Writable contracts.','Matching method signatures is not enough; throwing UnsupportedOperationException can violate expectations.','Any subtype should behave acceptably wherever the parent contract is expected.'),
    entry('isp','Interface Segregation Principle','Clients should depend only on operations they actually need. Split broad role interfaces into cohesive capabilities.','Violation: Printer interface demands scan(), fax(), print(). Fix: Printable, Scannable, Faxable.','Too many tiny interfaces can obscure the domain; divide along real client needs.','Design focused interfaces so consumers aren’t forced to implement unused methods.'),
    entry('dip','Dependency Inversion Principle','High-level policies and low-level details should depend on stable abstractions; the abstraction should not be controlled by one detail.','Violation: CheckoutService constructs StripeGateway. Fix: inject PaymentProcessor via constructor.','Dependency inversion is a design principle; dependency injection is one mechanism to realize it.','Have business policy receive a PaymentProcessor contract rather than instantiate a gateway.'),
    entry('refactor-coupling','Refactor tight coupling','Find volatile dependencies, introduce an interface at the consumer boundary, inject the concrete implementation at composition root, then test with a fake.','Move from new SmtpClient() inside OrderService to constructor-injected Notifier; wire SmtpNotifier in main().','Do not inject every data class or wrap stable standard-library APIs without a reason.','Abstract external dependencies where tests, volatility, or alternate implementations justify the indirection.'),
  ]),
  section('patterns','04','Design patterns','Recognize recurring trade-offs, not patterns to memorize blindly.','Patterns',[
    entry('singleton','Singleton','Guarantees one instance within a scope and provides global access; safe initialization and explicit lifecycle management matter.','Java enum singleton handles basic thread-safe initialization; a DI container singleton scope supports injectable services.','Global mutable state couples tests; in distributed systems “singleton” is only per process.','Use when there truly must be one instance per scope; otherwise inject a shared instance.',{pattern:'Creational',when:'A process-wide immutable registry or unique coordinator with a clearly defined scope.',avoid:'When it primarily hides a global dependency or mutable shared state.',recipe:'Define scope → create thread-safe instance → make dependencies explicit → document teardown.'}),
    entry('factory','Factory Method','A method delegates object creation to an override or creation boundary so clients do not hard-code concrete types.','DocumentParserFactory.create(format) can return PdfParser or CsvParser.','A static helper named create is not necessarily the GoF Factory Method pattern.','Use a factory when construction logic or concrete selection would otherwise leak into clients.',{pattern:'Creational',when:'Creation needs branching, configuration, or subtype-specific specialization.',avoid:'A simple constructor with no meaningful variability.',recipe:'Define product contract → move construction behind factory → keep client on contract.'}),
    entry('abstract-factory','Abstract Factory','Creates families of related objects without exposing concrete classes; ensures a consistent family of components.','LightThemeFactory creates matching Button, Menu, and Dialog; DarkThemeFactory creates the dark family.','If you only create one kind of object, a simple factory is easier.','Factory Method creates a product through one method; Abstract Factory builds compatible families.',{pattern:'Creational',when:'Multiple related products must be swapped together.',avoid:'Only one independent product needs creation.',recipe:'Identify product family → create family factory interface → add concrete families → inject chosen factory.'}),
    entry('builder','Builder','Builds a complex object step by step, often handling optional fields, validation, and immutable final objects.','HttpRequest.builder().url(...).timeout(...).header(...).build().','A builder is unnecessary for a two-field value object with a clear constructor.','Use Builder when construction becomes hard to read or requires validated combinations.',{pattern:'Creational',when:'Many optional configuration parameters or staged object construction.',avoid:'Small objects with few required parameters.',recipe:'Collect settings → validate at build() → construct immutable result.'}),
    entry('strategy','Strategy','Encapsulates interchangeable algorithms behind one interface so behavior can be selected without editing the caller.','Checkout chooses a ShippingCostStrategy for standard, express, or international orders.','A switch with two fixed tiny branches can be more readable; strategies add objects and indirection.','Use Strategy to swap independently evolving algorithms at runtime.',{pattern:'Behavioral',when:'Several policies vary independently and may change at runtime.',avoid:'Simple closed conditionals with no growth.',recipe:'Extract algorithm interface → implement policies → inject or select strategy → delegate.'}),
    entry('observer','Observer','Observers subscribe to updates from a subject; the subject broadcasts changes without knowing downstream implementation details.','OrderPlaced event triggers an email subscriber and an analytics subscriber.','Subscriptions need cleanup; synchronous observers can block or reenter publishers; distributed event delivery is more complex.','Use Observer for decoupled one-to-many reactions, with explicit delivery and failure semantics.',{pattern:'Behavioral',when:'Multiple listeners need to react to changes independently.',avoid:'A single essential synchronous collaborator is clearer as a direct call.',recipe:'Define event → subscribe listeners → publish → handle errors, order, and unsubscribe.'}),
    entry('decorator','Decorator','Wraps an object implementing the same interface and composes additional behavior before or after delegating.','BufferedReader wraps Reader; MetricsHttpClient wraps HttpClient.','Deep decorator chains can complicate debugging and ordering.','Decorator adds responsibilities while preserving the component contract.',{pattern:'Structural',when:'Optional layered behavior such as logging, caching, buffering.',avoid:'Only one fixed behavior that belongs in the original implementation.',recipe:'Implement same interface → store wrapped object → delegate and extend.'}),
    entry('adapter','Adapter','Converts one interface into another so incompatible APIs can work together.','LegacyXmlClient becomes a modern CustomerRepository using a wrapper that translates calls and data.','Adapters should translate contracts, not silently erase important semantics or errors.','Use Adapter when integrating an incompatible interface without changing its code.',{pattern:'Structural',when:'Integrating legacy, vendor, or external APIs with a stable internal contract.',avoid:'The APIs already match and adding a wrapper serves no purpose.',recipe:'Define target contract → hold adaptee → translate inputs, outputs, and errors.'}),
    entry('proxy','Proxy','A stand-in that controls access to another object, possibly adding lazy loading, caching, security, or remote communication.','ImageProxy loads a large image on first display; a security proxy checks authorization.','Proxy controls access; Decorator emphasizes adding behavior. Real implementations can overlap.','Use Proxy when access to a real object requires a managed boundary.',{pattern:'Structural',when:'Lazy loading, access checks, remote calls, or lifecycle management.',avoid:'No access mediation is needed.',recipe:'Mirror subject interface → mediate call → forward to real subject.'}),
    entry('template-method','Template Method','A base class defines an algorithm’s fixed skeleton while subclasses override selected steps.','AbstractList in Java supplies some operations using subclasses’ core methods such as get() and size().','Inherited hooks can create fragile hierarchies; Strategy often offers better runtime variation.','Template Method reuses a fixed workflow with subclass-customizable steps.',{pattern:'Behavioral',when:'Algorithm sequence is stable but a few steps differ.',avoid:'Behavior must be varied independently or at runtime.',recipe:'Define template algorithm → extract hooks → implement variants in subclasses.'}),
    entry('chain','Chain of Responsibility','Routes a request through a sequence of handlers, each of which may process or pass it along.','HTTP middleware chain: authentication → rate limit → tracing → route handler.','Ordering and short-circuit behavior must be intentional and documented.','Use a handler chain for composable ordered request processing.',{pattern:'Behavioral',when:'Several optional checks or middleware steps compose in order.',avoid:'A fixed short procedure is easier to understand.',recipe:'Define handler contract → link handlers → choose pass/stop rule → test ordering.'}),
    entry('command','Command','Encapsulates an action as an object, enabling queuing, audit, undo, retries, and remote execution.','Text editor stores InsertTextCommand and DeleteTextCommand for undo/redo.','Undo is not automatically possible; commands need reversibility or compensating actions.','Use Command when requests themselves need lifecycle, history, or scheduling.',{pattern:'Behavioral',when:'Operations are queued, logged, retried, or undone.',avoid:'A direct method call is entirely sufficient.',recipe:'Represent action + inputs → execute → optionally undo or compensate.'}),
    entry('state','State','Represents state-dependent behavior as separate state objects; transitions change the active state and behavior.','VendingMachine states: Idle, HasMoney, Dispensing, SoldOut.','State and Strategy can have similar shapes; State includes allowed transitions and lifecycle.','Use State when behavior and legal transitions depend heavily on the current state.',{pattern:'Behavioral',when:'Many states with distinct rules and transitions.',avoid:'Two simple states with few conditions.',recipe:'List states/transitions → define state contract → implement transitions → reject invalid actions.'}),
    entry('memento','Memento','Captures and restores an object’s state while minimizing exposure of its internals; often paired with Command for undo.','A drawing editor saves immutable snapshots of document state for restore checkpoints.','Snapshots can be expensive or leak private state; use diffs or retention limits if necessary.','Use Memento for undo, checkpoints, or rollback when state can be captured safely.',{pattern:'Behavioral',when:'Need restore points without exposing internal representation.',avoid:'Full snapshots are enormous or operations are fundamentally irreversible.',recipe:'Create snapshot → store in caretaker → restore via originator.'}),
    entry('flyweight','Flyweight','Shares immutable intrinsic state among many logical objects while supplying varying extrinsic data from callers.','A text editor shares one glyph/font description across thousands of character occurrences.','Shared objects must not accidentally store per-instance mutable data.','Use Flyweight to reduce duplication when many small objects have the same immutable state.',{pattern:'Structural',when:'Very large populations of objects repeat heavyweight immutable data.',avoid:'Object count/memory is not an actual bottleneck.',recipe:'Separate intrinsic/extrinsic state → cache shared flyweights → pass context per use.'}),
    entry('facade','Facade','Offers a simpler, focused entry point to a complex subsystem without removing the underlying capabilities.','CheckoutFacade coordinates inventory, pricing, payments, and shipping APIs.','Do not let one facade become an enormous god object owning every rule.','Use Facade to reduce client complexity and isolate subsystem orchestration.',{pattern:'Structural',when:'Subsystem API is complex, chatty, or unstable.',avoid:'Clients already need full fine-grained control.',recipe:'Choose common use cases → expose cohesive operations → orchestrate subsystem calls.'}),
  ]),
  section('internals','05','Language internals','Understand what abstractions cost and what the runtime really does.','Advanced',[
    entry('vtable','Virtual tables & dispatch','C++ implementations commonly use vtables/vptrs for virtual dispatch; Java uses JVM-specific method tables and optimizations, not a mandated C++-style layout.','Calling shape.draw() with a base reference can select Circle.draw(); JVM JIT may inline/devirtualize hot paths.','Dynamic dispatch is not always a vtable lookup; compiler/runtime may optimize it away.','Virtual dispatch resolves an implementation based on runtime type; exact mechanics are implementation-dependent.'),
    entry('mro','Python MRO / C3','Python C3 linearization creates a consistent order honoring local parent precedence and monotonicity. inspect MyClass.__mro__ to see the actual lookup path.','For class D(B,C), with B(A) and C(A), typical order is D,B,C,A,object.','super() follows the next item in MRO, not necessarily the lexical parent class.','MRO determines method lookup and cooperative super() behavior in multiple inheritance.'),
    entry('metaclass','Metaclasses / __new__ / __init__','__new__ creates an instance, __init__ initializes it, and a metaclass controls class creation. Most applications do not need custom metaclasses.','An immutable subclass may customize __new__; frameworks may register models during class creation.','__init__ is not the constructor that allocates the object; __new__ handles creation.','Reach for decorators or class hooks before introducing a metaclass.'),
    entry('copy','Shallow vs deep copy','A shallow copy duplicates the outer container but keeps references to nested objects. A deep copy recursively duplicates reachable objects, subject to copy semantics.','Copying a Cart with mutable LineItems shallowly allows nested edits to affect both carts.','Deep copying DB connections, locks, identity-bearing entities, or cyclic graphs is rarely desirable.','Copy strategy depends on identity and ownership of nested state.'),
    entry('cloning','Cloning pitfalls','Object clones must define identity, nested mutation behavior, resource ownership, invariants, and subclass handling.','Java clone() can bypass constructor assumptions; an explicit copy constructor or factory is often easier to reason about.','Cloning should not duplicate file descriptors, locks, or database sessions without careful policy.','Prefer explicit copying APIs that document shallow/deep semantics and preserve invariants.'),
    entry('gc','Garbage collection','Reference counting releases most objects when counts reach zero but struggles with cycles; tracing collectors mark reachable objects and sweep/reclaim unreachable memory. Generational GC exploits object age patterns.','A long-lived cache retaining references causes a logical memory leak even with GC.','GC does not guarantee when file handles are closed; collectors and algorithms differ by runtime.','GC manages reachable heap memory; explicit resource management and retention policies remain necessary.'),
    entry('memory-leaks','Memory leaks and resource leaks','In managed languages, retained references, event listeners, static maps, and queues can keep unwanted objects alive. In reference-counting systems, cycles may matter.','Observer listener never unsubscribed from a long-lived publisher, retaining an entire UI view.','Circular references are not universally leaks—tracing GC handles many cycles.','Investigate retention graphs and lifetimes, not only allocations.'),
    entry('immutability','Immutability','Immutable objects cannot change their externally observable state after creation. They simplify sharing, reasoning, hashing, and concurrency.','A Money value object stores final amount and currency, and add() returns a new Money.','A final reference or shallowly unmodifiable collection does not guarantee deep immutability.','Immutable values reduce coordination costs because their state cannot race or drift.'),
    entry('di-ioc','Dependency Injection & IoC','Dependency injection supplies collaborators from outside; inversion of control means a framework or caller manages flow/lifecycle instead of objects constructing dependencies themselves.','Constructor-inject Repository into OrderService; a DI container wires implementation, scope, and cleanup.','A DI framework is optional: manually creating dependencies in main() is still DI.','DI makes dependencies explicit and testable, while IoC describes broader control flow inversion.'),
  ]),
  section('design','06','Object-oriented design','Practice finding boundaries under real constraints.','OOD',[
    entry('parking','Design a parking lot','Model parking spots, vehicles, tickets, entry/exit, allocation strategies, pricing rules, and concurrent arrivals.','Classes: ParkingLot, Floor, Spot, Vehicle, Ticket, SpotAllocator, FeePolicy.','Avoid racing allocations and treating spot availability as an eventually consistent boolean.','Start with capacity/vehicle types; enforce one active ticket per parked vehicle; synchronize allocation.'),
    entry('library','Library management system','Separate book metadata from physical copies, member borrowing, reservation queues, fines, and availability.','Classes: Book, BookCopy, Member, Loan, Hold, Catalog, LendingService.','Do not treat a Book title as a uniquely borrowable copy.','Distinguish Book from BookCopy, then model loan state and reservation rules.'),
    entry('ecommerce','E-commerce cart and payments','Separate mutable cart intent, priced checkout snapshot, order lifecycle, payment attempts, and inventory reservations.','Classes: Cart, CartItem, Order, OrderLine, PaymentAttempt, PaymentProcessor, InventoryReservation.','Do not charge twice on retries; payments need idempotency and state transitions.','Snapshot prices at order creation and model payment attempts independently of orders.'),
    entry('vending','Vending machine','Use a state machine for selection, inserted money, dispensing, change, and out-of-stock/error recovery.','Classes: VendingMachine, Slot, Product, Inventory, PaymentSession, State.','Avoid mixing change calculation with the hardware dispensation command.','Represent allowed transitions and atomic stock decrement before dispensing.'),
    entry('atm','ATM','Model authenticated sessions, commands, account balances, withdrawal constraints, and coordination with cash inventory and bank systems.','Classes: ATM, Session, CardReader, BankGateway, CashDispenser, WithdrawalTransaction.','A bank debit followed by dispenser failure requires reversal/reconciliation logic.','Keep physical device operations separate from transaction and authorization policy.'),
    entry('url','URL shortener','Focus on Link, AliasGenerator, Repository, RedirectService, expiration, and collision resolution; discuss persistence and caching.','Classes: ShortLink, SlugGenerator, LinkRepository, RedirectService, AbusePolicy.','This has significant distributed-system concerns beyond a simple class diagram.','Make slug uniqueness explicit and model redirect behavior separately from link creation.'),
    entry('chess','Two-player chess / card game','Model immutable moves, turn validation, board state, pieces/cards, rules, and game lifecycle.','Classes: Game, Board, Player, Move, RulesEngine, Piece; use piece behavior carefully.','Putting every game rule inside subclassed Piece types creates scattered rule enforcement.','Centralize rule validation and treat Game as owner of legal state transitions.'),
    entry('restaurant','Restaurant and order system','Model tables/reservations, menu versions, orders, order lines, kitchen tickets, and split payments.','Classes: Table, Reservation, MenuItem, Order, OrderItem, KitchenTicket, Bill, Payment.','OrderItem price should be a snapshot: menu prices can change mid-service.','Separate ordering, kitchen preparation, and settling the bill.'),
    entry('notification','Notification system','Design channels, templates, preferences, delivery attempts, retries, and idempotent event handling.','Classes: Notification, Template, RecipientPreference, Channel, DeliveryAttempt, Dispatcher.','Do not promise exactly-once sending across external providers; handle duplicate delivery attempts.','Use channel strategies and explicit attempt states with bounded retries.'),
    entry('devices','Smartphone / device hierarchy','Identify actual capabilities rather than deriving every device from one oversized Device base type.','Interfaces: Callable, CameraCapable, NetworkConnected; composition: Phone has Camera, Modem, Battery.','An unsupported capability implemented by throwing is a design smell (LSP/ISP).','Prefer composition and role interfaces over a universal inheritance tree.'),
  ]),
  section('concurrency','07','Concurrency & OOP','Correctness when many calls interact at once.','Concurrency',[
    entry('thread-safety','Thread safety and locks','Protect shared mutable invariants with synchronization, locks, atomic operations, actor ownership, or immutability. Decide what the unit of atomicity is.','Transfer between two Accounts requires coordinated balance update, not two unrelated thread-safe getters.','Thread-safe methods individually do not make a compound check-then-act operation atomic.','Define the invariant first; choose synchronization boundaries that preserve it.'),
    entry('multithreading','OOP in multithreaded systems','Objects may be confined to a thread, shared immutably, or shared behind synchronized methods. API documentation should declare concurrency guarantees.','An immutable OrderSnapshot is freely shared; MutableCart belongs to one session; InventoryService synchronizes reservations.','Lock ordering, deadlocks, stale visibility, and unsafe publication remain concerns.','OOP provides encapsulation boundaries; thread safety depends on how shared state is coordinated.'),
    entry('singleton-thread','Thread-safe Singleton','In Java, enum singleton or initialization-on-demand holder are simple thread-safe options. Double-checked locking requires volatile for safe publication.','class Holder { static final Registry INSTANCE = new Registry(); }','Thread-safe initialization is distinct from thread-safe mutable operations on the instance.','Prefer DI-managed lifecycle; if a singleton is essential, ensure safe publication and guard state separately.'),
    entry('microservices-conc','Microservice concurrency','Each service has independent processes and failure modes. Object locks do not protect state across nodes; use DB constraints, idempotency keys, optimistic concurrency, queues, or sagas.','Two requests attempt to reserve the last inventory unit: conditional DB update ensures only one succeeds.','A synchronized method in one JVM does not serialize requests on a second server.','Use durable transactional boundaries for distributed consistency, not local object locks.'),
  ]),
  section('behavioral','08','Behavioral interviews','Tell convincing stories about decisions and trade-offs.','Stories',[
    entry('debug-story','Debugging a complex OOP bug','Explain symptoms, hypothesis, minimal reproduction, contract violation, root cause, fix, and prevention.','A subclass violates a base interface invariant and introduces unexpected state after a refactor.','Do not claim a hypothetical incident happened to you. Tell an authentic story with evidence.','STAR: situation, task, actions/debugging, measurable result and prevention.'),
    entry('monolith-story','Refactoring monolith to services','Start with business boundaries, dependency graphs, data ownership, and incremental extraction; class boundaries do not directly map to service boundaries.','Extract Billing behind a clear API and events using a strangler pattern; keep one owner of billing records.','Splitting every class into a microservice creates a distributed monolith.','Begin with domain boundaries and migration strategy before deployment topology.'),
    entry('evolution-story','How your OOP approach evolved','Move from inheritance-for-reuse toward contracts, composition, invariants, and observed change axes.','Earlier: subclass for each report format. Later: ReportRenderer interface composed with independent data source.','Avoid repeating buzzwords without a concrete design decision.','Show an earlier choice, a failure or lesson, and an improved decision.'),
    entry('performance-story','Optimizing OOP performance','Measure allocation, dispatch, cache behavior, copying, and I/O before rewriting abstractions. Preserve correctness and benchmark again.','A hot path allocates thousands of temporary DTOs; profiling motivates batching and value reuse.','Vtable dispatch is rarely the bottleneck compared with DB, network, and allocation.','Describe profiling evidence, smallest effective change, and before/after metrics.'),
    entry('mentor-story','Mentoring juniors on OOP','Use a clear counterexample and let teammates compare testability and change cost; review APIs and invariants, not pattern counts.','Pair on a god-class refactor into cohesive collaborators and write a regression test.','Teaching SOLID as absolute rules discourages judgment.','Lead with context and trade-offs, then make the reasoning reusable.'),
    entry('inheritance-story','Inheritance to reduce redundancy','Describe where a shared stable contract and true is-a relationship justified a base type, and how you protected LSP.','A small hierarchy of parsers shares lifecycle methods while each implements parseBody().','Do not force inheritance merely to demonstrate knowledge; composition may be the better story.','Explain both the reuse benefit and why substitutability remained valid.'),
    entry('disagreement-story','Disagreements on design','Clarify constraints, write down alternatives, compare change frequency and testability, prototype if needed, then align on a decision record.','Team debates a strategy interface versus three if statements; estimate anticipated variants and testing cost.','Do not frame teammates as inexperienced or dismiss concerns.','Show evidence-based collaboration and willingness to revise your position.'),
  ]),
  section('edge','09','Tricky questions','Precision matters more than memorized one-liners.','Edge cases',[
    entry('no-oop','Can an app run without OOP?','Yes. Procedural, functional, and data-oriented programs can build complete applications; many systems use multiple paradigms.','A CLI parser can be functional without domain class hierarchies.','OOP is a design tool, not a fundamental runtime requirement.','Yes; choose paradigms based on domain, language, and constraints.'),
    entry('class-struct','Class vs struct','Meaning depends on language. In C++, class members are private by default and struct members public, but both can have methods/inheritance. C# struct is a value type; Java records are different again.','C++ struct Point {int x,y;} and class Point have nearly the same capabilities with differing defaults.','Do not say a struct always lives on the stack or never has methods.','Ask which language; “struct vs class” has no universal memory-layout answer.'),
    entry('class-memory','How much memory does a class occupy?','Instances occupy object storage, but class metadata, static fields, code and runtime representation also consume memory. Instance size depends on layout, headers, padding, and references.','One Java Object may have a header and alignment overhead even without user fields.','“A class occupies zero memory” is an oversimplification; the class definition need not create instance storage.','Distinguish per-instance memory from shared runtime class metadata and static storage.'),
    entry('operator-overload','Operator overloading','C++ supports user-defined overloads for selected existing operators, not new operators; you cannot overload ::, ., .*, ?:, or sizeof. Python uses special methods; Java disallows user-defined operator overloading (besides built-in String +).','C++ Matrix operator+(...) returns a sum; Python __add__ controls +.','An operator should preserve expected semantics; don’t overload + for unrelated side effects.','Language-specific; discuss supported operators and readability restrictions.'),
    entry('constructor-chaining','Constructor chaining','One constructor delegates to another in the same class or to a superclass to reuse initialization and maintain invariants.','Java User(String name) { this(name, "member"); }','Recursive constructor delegation is invalid; initialization order matters.','Centralize shared setup in one constructor to avoid conflicting validation.'),
    entry('equality','Java == / equals; Python is / ==','Java == compares primitive values or object identity, while equals() expresses class-defined logical equality. Python is checks identity; == dispatches equality methods.','new String("a").equals(new String("a")) is true while object identity differs.','If overriding Java equals(), also implement consistent hashCode(); Python equality can return NotImplemented.','Use logical equality for values and identity checks only when object sameness matters.'),
    entry('replace-switch','Replace conditionals with polymorphism?','Replace branches when variations have independent logic, grow often, or need external extension. Keep a switch when cases are small, closed, and easy to reason about.','Choose TaxPolicy for country-specific tax rules; keep a simple enum-to-label map as a switch.','“No if statements” is not an OOP design goal.','Evaluate change frequency, behavior complexity, and indirection costs.'),
    entry('getter-leak','How getters break encapsulation','A getter can return a reference to mutable internal state and allow callers to alter invariants without the object’s validation.','getItems() returns an internal ArrayList; callers clear() it. Return an immutable copy or controlled operations instead.','An unmodifiable view can still reflect underlying changes; a snapshot has different semantics.','Encapsulation requires guarding observable mutation, not merely marking fields private.'),
    entry('modern-composition','Why composition and interfaces win','Components are easier to isolate, test, and replace; interfaces separate contracts from implementations; shallow designs constrain change propagation.','A service receives AuditSink, Cache, and Repository rather than inheriting from a large FrameworkBaseService.','Composition introduces wiring cost and can become fragmented without clear ownership.','Prefer composition for changing capabilities; inherit only across stable subtype relationships.'),
    entry('oop-limits','Limitations of OOP','Layering, allocations, indirection, identity/state complexity, fragmented data layouts, and inheritance misuse can worsen simple or performance-sensitive tasks.','Data-oriented array transforms can outperform heaps of tiny objects for hot numeric loops.','OOP is not inherently slow; implementation, memory access, and workload determine costs.','Use OOP where behavior and invariants benefit from object boundaries, not everywhere.'),
  ]),
  section('uml','10','UML & communication','Express a design clearly before writing code.','UML',[
    entry('class-diagram','Class diagrams','Show types, attributes, operations, multiplicity, visibility, and relationships; omit noisy implementation detail in interviews.','Order contains 1..* OrderLine; Customer can place 0..* Orders.','Diagrams communicate constraints, not every getter or database column.','Draw just enough to show ownership, contracts, and cardinality.'),
    entry('uml-relationships','Relationship notation','Generalization: solid line with hollow triangle. Realization: dashed line with hollow triangle. Association: solid line. Aggregation: hollow diamond. Composition: filled diamond. Dependency: dashed arrow.','Order ◆── OrderLine (composition); Service - - > Repository (dependency).','Diamonds go at the whole/owner end; the arrow is not a substitute for lifecycle reasoning.','Choose notation based on semantics, especially ownership and substitutability.'),
    entry('sequence','Sequence diagrams','Show participants across the top and time down the page. Messages, returns, alt branches, and loops illustrate runtime collaboration.','Checkout → OrderService → PaymentGateway → Repository; failure branch issues rollback/compensation.','Sequence diagrams show interactions, not deployment or complete class structure.','Use sequence diagrams when order of calls and failure paths matter.'),
    entry('identify-objects','Identify classes and objects','Extract domain nouns, then validate each candidate has meaningful state, identity, invariants, and responsibility. Use verbs to discover behaviors and services.','In a library: BookCopy, Loan, Member are entities; BorrowingService coordinates rules.','Not every noun needs a class; some are values, attributes, or external systems.','Model rules and lifecycles first, then choose classes that protect them.'),
  ]),
];

