window.COMPARISONS = [
  {title:'Strategy vs State',left:'Strategy',right:'State',detail:'Both delegate to interchangeable objects. Strategy is selected to vary an algorithm; State models a finite set of conditions and valid transitions. State objects may determine the next state.',example:'Choose a shipping algorithm (Strategy) versus move an order from Paid → Fulfilled (State).'},
  {title:'Decorator vs Proxy',left:'Decorator',right:'Proxy',detail:'Both wrap the same contract. Decorator adds responsibility in layers; Proxy governs how or when the real object is accessed. Logging can appear in both.',example:'Add compression around a stream (Decorator); lazily load a remote image (Proxy).'},
  {title:'Factory vs Abstract Factory',left:'Factory Method',right:'Abstract Factory',detail:'Factory Method provides an overridable creation method for one product type. Abstract Factory creates a matched family of different related products.',example:'createButton() by subclass versus createButton(), createMenu(), createDialog() for a whole theme.'},
  {title:'Adapter vs Facade',left:'Adapter',right:'Facade',detail:'Adapter makes an incompatible API match an expected contract. Facade simplifies access to multiple or complex existing interfaces.',example:'Wrap legacy XML client as CustomerRepo (Adapter); expose checkout() over payment + stock + delivery (Facade).'},
];

window.DESIGN_CASES = [
 {id:'parking',title:'Parking lot',difficulty:'Intermediate',time:'25 min',icon:'P',brief:'A multilevel parking facility supports motorcycles, cars, and trucks, tickets, and pay-on-exit pricing.',requirements:['Allocate a compatible free spot; never double-allocate.','Issue entry ticket and compute exit fee from a pricing policy.','Show capacity by floor and vehicle type.','Handle concurrent entry and a full lot.'],classes:[['ParkingLot','owns floors; aggregates availability'],['Floor','owns spots'],['ParkingSpot','type, availability, active ticket'],['Ticket','vehicle, entry time, exit time, status'],['SpotAllocator','selects a matching spot'],['FeePolicy','calculates amount due']],relations:['ParkingLot ◆─ Floor ◆─ ParkingSpot','Ticket ─ Vehicle','EntryService → SpotAllocator','ExitService → FeePolicy'],twist:'Two cars arrive for the last available spot simultaneously.',solution:'Make allocation an atomic operation within a floor/spot repository transaction. Model an active ticket tied to one spot. Keep pricing behind FeePolicy and spots behind SpotAllocator. Reject entry explicitly if no eligible spot is available.',followup:'How would you implement reserved spaces and electric charging without subclass explosion?'},
 {id:'library',title:'Library system',difficulty:'Intermediate',time:'25 min',icon:'L',brief:'Members borrow physical book copies; popular titles have hold queues and overdue fines.',requirements:['Catalog by title/author/ISBN, track individual copies.','Borrow/return with due dates and borrowing limits.','Queue holds and notify eligible members.','Calculate overdue fines by policy.'],classes:[['Book','ISBN and bibliographic metadata'],['BookCopy','barcode, status, location'],['Member','membership status and limits'],['Loan','copy, dates, borrower'],['Hold','reservation priority'],['LendingService','enforces transaction rules']],relations:['Book 1 ─ 0..* BookCopy','Member 1 ─ 0..* Loan','BookCopy 1 ─ 0..1 active Loan','Book 1 ─ 0..* Hold'],twist:'A reserved copy is returned while another patron is at the desk.',solution:'BookCopy and Book are separate entities. On return, atomically transition the copy into held-for-member rather than generally available; LendingService checks hold queue priority and loan limits.',followup:'What data needs an index, and how would you handle overdue jobs?'},
 {id:'ecommerce',title:'Checkout & payments',difficulty:'Advanced',time:'35 min',icon:'E',brief:'A shopper checks out a cart with coupons, inventory reservation, and payment retries.',requirements:['Compute totals with consistent discounts/tax rules.','Create an immutable order snapshot from a mutable cart.','Support multiple gateways and payment attempts.','Prevent duplicate charges and reconcile failures.'],classes:[['Cart','mutable shopping intent'],['Order','snapshot and lifecycle'],['OrderLine','unit price, tax, quantity'],['PaymentAttempt','idempotency key, status'],['PaymentProcessor','provider abstraction'],['InventoryReservation','holds stock with expiry']],relations:['Cart → CheckoutService','Order ◆─ OrderLine','Order 1 ─ 0..* PaymentAttempt','CheckoutService → PaymentProcessor'],twist:'Provider times out after charging; client retries.',solution:'Persist order and payment intent with a unique idempotency key; reuse that key on provider retries. Treat timeout as unknown, not failed, until reconciliation. Snapshot prices and reserve stock before confirming order.',followup:'How do you prevent overselling during flash sales?'},
 {id:'vending',title:'Vending machine',difficulty:'Intermediate',time:'20 min',icon:'V',brief:'A vending machine accepts money, dispenses stocked products, and returns change.',requirements:['Choose product and validate inventory.','Accept money and handle insufficient funds.','Dispense and calculate change correctly.','Handle cancel, sold-out, and mechanical failure.'],classes:[['VendingMachine','state and coordination'],['Slot','item + count'],['Product','price and identity'],['PaymentSession','inserted funds'],['Inventory','stock reservation'],['MachineState','allowed user actions']],relations:['VendingMachine ◆─ Slot','VendingMachine → MachineState','VendingMachine → PaymentSession'],twist:'Dispensing mechanism fails after funds are accepted.',solution:'Define Idle → Selected → Paid → Dispensing → Complete/Refund states. Record purchase intent before driving hardware; on failure, offer refund or recovery while keeping inventory/accounting consistent.',followup:'How would you plug in NFC payment with little code change?'},
 {id:'atm',title:'ATM',difficulty:'Advanced',time:'30 min',icon:'A',brief:'A terminal authenticates cards, requests withdrawals, and dispenses physical cash.',requirements:['Create session and authenticate with bank.','Validate withdrawal rules and cash availability.','Record transaction and drive dispenser.','Handle timeout, reversal, and receipts.'],classes:[['ATM','device orchestration'],['Session','card and auth state'],['BankGateway','authorization and debit'],['Withdrawal','transaction state'],['CashDispenser','hardware operation'],['CashInventory','denomination counts']],relations:['ATM → BankGateway','ATM → CashDispenser','Session 1 ─ 0..* Withdrawal'],twist:'Bank debit succeeds but dispenser jams.',solution:'Treat banking and physical dispensing as separate unreliable steps. Record transaction states, issue reversal/compensation when needed, and reconcile unknown outcomes. Avoid assuming two-phase atomicity with external hardware.',followup:'How would you pick denominations when cash is fragmented?'},
 {id:'url',title:'URL shortener',difficulty:'Intermediate',time:'25 min',icon:'U',brief:'Create short aliases that redirect users and may expire or be disabled.',requirements:['Create a unique alias or accept custom slugs.','Redirect quickly and preserve HTTP semantics.','Expire, disable, and validate links.','Record view metrics without blocking redirects.'],classes:[['ShortLink','slug, target, expiration'],['SlugGenerator','unique candidates'],['LinkRepository','lookup and uniqueness'],['RedirectService','validates and redirects'],['AnalyticsPublisher','async click events']],relations:['RedirectService → LinkRepository','CreateLinkService → SlugGenerator','RedirectService → AnalyticsPublisher'],twist:'Two clients request the same custom slug at once.',solution:'Enforce a unique database constraint on slug, not only application checks. Handle conflict explicitly. Cache redirects with appropriate invalidation/TTL for disabled or expired links.',followup:'What changes when redirects reach 100k per second?'},
 {id:'chess',title:'Chess / card game',difficulty:'Advanced',time:'35 min',icon:'C',brief:'Implement two-player turns, legal actions, state, and end-of-game rules.',requirements:['Represent board/cards and active player.','Generate and validate legal moves.','Apply actions, record history, detect winner.','Support game save/replay.'],classes:[['Game','phase, players, turn'],['Board','square occupancy'],['Move','immutable action'],['RulesEngine','validation and endgame'],['Piece','type, color, location'],['MoveHistory','applied actions']],relations:['Game ◆─ Board','Game → RulesEngine','Game ◆─ MoveHistory','Board 1 ─ 0..* Piece'],twist:'One move exposes a king to check; how is it rejected?',solution:'Validate a proposed Move against an isolated board state or reversible transaction, including king safety. Game owns turn changes and history only after validation succeeds. Keep move legality cohesive inside RulesEngine.',followup:'Where would you place castling and en passant logic?'},
 {id:'restaurant',title:'Restaurant orders',difficulty:'Intermediate',time:'30 min',icon:'R',brief:'Tables take orders over time; kitchen handles tickets; diners can split payment.',requirements:['Create reservations and seat parties.','Take orders with menu-price snapshots.','Send items to kitchen and track prep state.','Split and settle a bill.'],classes:[['Table','capacity, occupied state'],['Reservation','slot and party'],['Order','table and order lifecycle'],['OrderItem','snapshot price, quantity'],['KitchenTicket','prep state'],['Bill','charges and settlement']],relations:['Table 1 ─ 0..* Order','Order ◆─ OrderItem','Order 1 ─ 0..* KitchenTicket','Order 1 ─ 1 Bill'],twist:'Menu price changes midway through a long dinner.',solution:'Snapshot each ordered item price and tax policy when accepted; do not recalculate historical items from current menu. Separate kitchen events from billing status and reservation state.',followup:'How would you support splitting one item between two guests?'},
 {id:'notification',title:'Notification service',difficulty:'Advanced',time:'35 min',icon:'N',brief:'Send templated SMS, email, and push respecting preferences and transient provider failures.',requirements:['Render templates with versioned variables.','Apply channel opt-outs and quiet hours.','Retry with backoff without unbounded duplicates.','Record delivery status and observability.'],classes:[['Notification','intent and recipient'],['Template','rendering contract'],['PreferencePolicy','allowed channels/time'],['DeliveryChannel','email/SMS/push strategy'],['DeliveryAttempt','provider response and status'],['Dispatcher','queue orchestration']],relations:['Dispatcher → PreferencePolicy','Dispatcher → DeliveryChannel','Notification 1 ─ 0..* DeliveryAttempt'],twist:'A queue redelivers the same message after process crash.',solution:'Use a stable message ID and dedupe store, idempotent attempt creation, and provider-specific reconciliation. Document at-least-once delivery and the possibility of external duplicate sends.',followup:'How would you implement per-user rate limits?'},
 {id:'devices',title:'Device capabilities',difficulty:'Foundational',time:'20 min',icon:'D',brief:'Model smartphones, tablets, watches, cameras, and other overlapping capabilities.',requirements:['Devices have different independent features.','Avoid no-op unsupported methods.','Share reusable camera, radio, and battery behavior.','Support future device types.'],classes:[['Device','identity, diagnostics'],['Camera','capturing images'],['Battery','state and charging'],['NetworkAdapter','connectivity'],['Callable','optional capability'],['CaptureCapable','optional capability']],relations:['Phone ◆─ Camera','Phone ◆─ Battery','Watch ◆─ Battery','Phone ⇢ Callable','Camera ⇢ CaptureCapable'],twist:'A tablet gains calling support after a hardware upgrade.',solution:'Use small capability interfaces and composed hardware components, not one inheritance ladder. Models can expose different contracts based on supported capabilities while maintaining valid defaults.',followup:'Would runtime feature discovery be preferable to compile-time interfaces?'},
];

